        oCheckBoxs[nRow].checked = (sAllChecked == "Y") ? true : false;
        scwin.fn_GridCtrl(oCheckBoxs[nRow]);
    }
};




/********************************************** 
 * 함수명   : fn_AllStdCheck
 * 설명       : 기본정보 체크 시 체크.
 ***********************************************/
scwin.fn_AllStdCheck = function() {

	//----W-Craft WebSquare 변환 확인: getElementsByName----//
    var oCheckBoxs = document.getElementsByName("std_ckb");
